using System;
using System.Linq;
using Creezio.Switcher;

internal static class ProcessResourceTests
{
    private static void Assert(bool value,string message){if(!value)throw new Exception(message);}
    private static ResourceProcess P(int pid,int parent,long start,double cpu=0){return new ResourceProcess{Pid=pid,Parent=parent,Started=start,Name="ChatGPT.exe",Resident=pid*1024,PrivateBytes=pid*2048,CpuSeconds=cpu};}
    private static ResourceScope Scope(string id,int pid,long start,int host=0,long hostStart=0){return new ResourceScope{Id=id,Name=id,Account="fixture@example.com",Managed=true,Home="fixture",State=new InstanceState{Running=true,Phase="running",DesktopPid=pid,DesktopStartTicks=start,HostPid=host,HostStartTicks=hostStart}};}
    internal static void RunAll(Action<string,Action> check)
    {
        check("resource families use the nearest identified instance and count each PID once",()=>{var rows=new[]{P(10,0,100),P(11,10,110),P(20,10,120),P(21,20,130),P(30,21,140)};var data=ProcessResources.Build(rows,new[]{Scope("primary",10,100),Scope("other",20,120)},new ResourceProcess[0],0,4);Assert(data.Groups[0].Processes.Select(p=>p.Pid).SequenceEqual(new[]{10,11})&&data.Groups[1].Processes.Length==3,"another instance consumed by parent");Assert(data.Groups.Sum(g=>g.Processes.Length)==5&&data.Groups.Sum(g=>g.Resident)==rows.Sum(p=>p.Resident.Value),"double count");});
        check("resource attribution refuses a recycled root PID",()=>{var data=ProcessResources.Build(new[]{P(10,0,500),P(11,10,510)},new[]{Scope("old",10,100)},new ResourceProcess[0],0,4);Assert(data.Groups[0].Processes.Length==0&&data.Unassigned.Length==2&&data.Groups[0].Partial,"recycled PID accepted");});
        check("resource attribution rejects recycled parents and cycles",()=>{var rows=new[]{P(10,0,500),P(11,10,100),P(20,21,200),P(21,20,200)};var data=ProcessResources.Build(rows,new[]{Scope("a",10,500)},new ResourceProcess[0],0,4);Assert(data.Groups[0].Processes.Length==1&&data.Unassigned.Length==3,"invalid genealogy");});
        check("resource attribution includes the managed host without capturing sibling instances",()=>{var rows=new[]{P(10,0,100),P(20,10,120),P(21,20,130),P(30,10,140)};var data=ProcessResources.Build(rows,new[]{Scope("switcher",10,100),Scope("managed",21,130,20,120)},new ResourceProcess[0],0,4);Assert(data.Groups[1].Processes.Length==2&&data.Groups[0].Processes.Length==2,"host attribution");});
        check("resource CPU measures delta over all logical processors",()=>{var data=ProcessResources.Build(new[]{P(10,0,100,8)},new[]{Scope("a",10,100)},new[]{P(10,0,100,4)},2,4);Assert(data.Groups[0].Cpu==50,"CPU normalization");});
        check("resource CPU keeps the measured lower bound when a new child has no baseline",()=>{var data=ProcessResources.Build(new[]{P(10,0,100,8),P(11,10,110,1)},new[]{Scope("a",10,100)},new[]{P(10,0,100,4)},2,4);Assert(data.Groups[0].Cpu==50&&data.Groups[0].CpuPartial,"partial CPU hidden or claimed complete");});
        check("resource CPU never reuses old counters after PID reuse or a long pause",()=>{foreach(double elapsed in new[]{2d,40d}){var data=ProcessResources.Build(new[]{P(10,0,200,50)},new[]{Scope("a",10,200)},new[]{P(10,0,100,1)},elapsed,4);Assert(data.Groups[0].Cpu==null,"stale CPU counter used");}var reset=ProcessResources.Build(new[]{P(10,0,100,1)},new[]{Scope("a",10,100)},new[]{P(10,0,100,20)},2,4);Assert(reset.Groups[0].Cpu==null,"negative CPU count");});
        check("resource unavailable measurements are partial rather than reported as zero",()=>{var child=P(11,10,120);child.Resident=null;child.PrivateBytes=null;child.CpuSeconds=null;var data=ProcessResources.Build(new[]{P(10,0,100),child},new[]{Scope("a",10,100)},new ResourceProcess[0],0,4);Assert(data.Groups[0].Partial&&data.Groups[0].Cpu==null&&data.Groups[0].Processes.Length==2,"unknown value treated as measured zero");});
        check("resource roots with conflicting identities fail closed",()=>{bool failed=false;try{ProcessResources.Build(new[]{P(10,0,100)},new[]{Scope("a",10,100),Scope("b",10,100)},new ResourceProcess[0],0,4);}catch(InvalidOperationException){failed=true;}Assert(failed,"ambiguous roots accepted");});
        check("resource classifier exposes roles without exposing command-line secrets",()=>{Assert(ProcessResources.Role("ChatGPT.exe","--type=renderer secret=private")=="Rendu de fenêtre"&&ProcessResources.Role("node.exe","token=private")=="Plugin, script ou serveur Node","raw arguments exposed");});
        check("resource activity considers pinned and visible local chats, excluding remote work",()=>{var value=Json.Read<object>("{\"threads\":[{\"id\":\"a\",\"kind\":\"codex\",\"hostId\":\"remote\",\"status\":\"active\"},{\"id\":\"b\",\"kind\":\"codex\",\"hostId\":\"local\",\"status\":\"idle\"}],\"pinnedThreads\":[{\"id\":\"c\",\"kind\":\"codex\",\"hostId\":\"local\",\"status\":\"active\",\"title\":\"Fixture\"}]}");var activity=ResourceActivity.FromSidebar(value);Assert(activity.State=="busy"&&activity.Active==1&&activity.Titles.Single()=="Fixture","active chat missed");});
        check("resource activity does not interpret missing status or failed hosts as idle",()=>{foreach(string json in new[]{"{}","{\"threads\":[],\"pinnedThreads\":[],\"unavailableHosts\":[\"local\"]}","{\"threads\":[{\"id\":\"a\",\"kind\":\"codex\",\"status\":\"unknown\"}],\"pinnedThreads\":[]}"})Assert(ResourceActivity.FromSidebar(Json.Read<object>(json)).State=="unknown","unknown activity accepted");});
        check("resource visible idle is a hint and never a complete close authorization",()=>{var a=ResourceActivity.FromSidebar(Json.Read<object>("{\"threads\":[{\"id\":\"a\",\"kind\":\"codex\",\"status\":\"notLoaded\"}],\"pinnedThreads\":[]}"));Assert(a.State=="visible_idle"&&a.Message.Contains("contrôle complet"),"sidebar used as complete idle check");});
    }
}
